pub struct User {
    pub name: String,
    pub age: u32,
}

fn escape_json_string(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

/// 手动拼 JSON（不依赖 serde）：把 &[User] 序列化为 JSON 数组字符串。
/// 例：to_json(&[User{name:"Ali".into(),age:25}]) => `[{"name":"Ali","age":25}]`
pub fn to_json(users: &[User]) -> String {
    let mut out = String::from("[");
    for (i, u) in users.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(&format!(
            "{{\"name\":\"{}\",\"age\":{}}}",
            escape_json_string(&u.name),
            u.age
        ));
    }
    out.push(']');
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_to_json_single_user() {
        let users = vec![User {
            name: "Ali".to_string(),
            age: 25,
        }];
        assert_eq!(to_json(&users), r#"[{"name":"Ali","age":25}]"#);
    }

    #[test]
    fn test_to_json_multiple_users() {
        let users = vec![
            User {
                name: "Ali".to_string(),
                age: 25,
            },
            User {
                name: "Bob".to_string(),
                age: 30,
            },
        ];
        assert_eq!(
            to_json(&users),
            r#"[{"name":"Ali","age":25},{"name":"Bob","age":30}]"#
        );
    }

    #[test]
    fn test_to_json_empty() {
        assert_eq!(to_json(&[]), "[]");
    }

    #[test]
    fn test_to_json_escapes_special_chars() {
        let users = vec![User {
            name: "A\"B".to_string(),
            age: 1,
        }];
        assert_eq!(to_json(&users), r#"[{"name":"A\"B","age":1}]"#);
    }
}
